import crypto from 'node:crypto';
import fs from 'node:fs';
import type { EnvHandler } from '@teambit/envs';
import type {
  ConfigFile,
  ConfigWriterEntry,
  ExtendingConfigFile,
  GenerateExtendingConfigFilesArgs,
} from '@teambit/workspace-config-files';

const BIT_GENERATED_OXLINT_CONFIG_COMMENT = '// bit-generated-oxlint-config';

const sha1 = (content: string) =>
  crypto.createHash('sha1').update(content).digest('hex');

export type OxlintConfigWriterOptions = {
  name?: string;
  /**
   * absolute path to the Oxlint config file to write into the workspace.
   */
  configPath: string;
};

export class OxlintConfigWriter implements ConfigWriterEntry {
  id = 'oxlint';

  patterns = [
    '**/.oxlintrc.{json,jsonc}',
    '**/oxlint.config.{ts,mts}',
  ];

  constructor(public name: string, private configPath: string) {}

  calcConfigFiles(): ConfigFile[] {
    const content = fs.readFileSync(this.configPath, 'utf8');
    const hash = sha1(content);
    return [{ name: `oxlintrc.bit.${hash}.json`, content, hash }];
  }

  generateExtendingFile({
    writtenConfigFiles,
  }: GenerateExtendingConfigFilesArgs): ExtendingConfigFile | undefined {
    const configFile = writtenConfigFiles.find((file) =>
      file.name.includes('oxlintrc.bit.')
    );
    if (!configFile) return undefined;

    // Oxlint only inherits rules, plugins, and overrides through `extends`.
    // Copying the complete source config keeps root-only fields such as
    // options.typeAware, options.typeCheck, settings, and ignorePatterns active.
    const content = `${BIT_GENERATED_OXLINT_CONFIG_COMMENT}\n${configFile.content}`;
    return {
      content,
      hash: sha1(content),
      name: '.oxlintrc.json',
      extendingTarget: configFile,
      useAbsPaths: false,
    };
  }

  isBitGenerated(filePath: string): boolean {
    return fs
      .readFileSync(filePath, 'utf8')
      .includes(BIT_GENERATED_OXLINT_CONFIG_COMMENT);
  }

  static from(
    options: OxlintConfigWriterOptions
  ): { name: string; handler: EnvHandler<OxlintConfigWriter> } {
    const name = options.name || 'OxlintConfigWriter';
    return {
      name,
      handler: () => new OxlintConfigWriter(name, options.configPath),
    };
  }
}
